/*
 * config.h - every pin, rate and tunable constant in one place.
 *
 * Pin numbers are ESP32-S3 GPIO numbers (not Feather silkscreen labels).
 * Feather label -> GPIO mapping is from Adafruit's ESP32-S3 Feather pinout;
 * double-check against the PrettyPins PDF before wiring.
 */
#pragma once

#include "sdkconfig.h"   /* generated by ESP-IDF from Kconfig + sdkconfig.defaults */

/* ---------------- Sampling ---------------- */
#define SG_SAMPLE_RATE_HZ        1000      /* spec S3: >= 1 kHz per channel */
#define SG_SAMPLE_PERIOD_US      (1000000 / SG_SAMPLE_RATE_HZ)

/* ---------------- FSRs (ADC1 only: GPIO1-10 on the S3) ---------------- */
/* Divider: 3V3 -- FSR -- node -- 10k -- GND, ADC reads node.
 * More force -> lower FSR resistance -> higher voltage -> bigger ADC count. */
#define SG_NUM_FSR               4
#define PIN_FSR_INSTEP           5         /* Feather D5  (ADC1_CH4) */
#define PIN_FSR_LACES            6         /* Feather D6  (ADC1_CH5) */
#define PIN_FSR_OUTSIDE          9         /* Feather D9  (ADC1_CH8) */
#define PIN_FSR_TOE              10        /* Feather D10 (ADC1_CH9) */

typedef enum {
    ZONE_INSTEP = 0,
    ZONE_LACES,
    ZONE_OUTSIDE,
    ZONE_TOE,
} sg_zone_t;

/* ---------------- I2C (IMU) ---------------- */
#define PIN_I2C_SDA              3         /* shared with STEMMA QT */
#define PIN_I2C_SCL              4
#define PIN_I2C_POWER            7         /* Feather: must be HIGH to power STEMMA QT */
#define SG_I2C_FREQ_HZ           400000

/* ---------------- SPI (microSD breakout) ---------------- */
#define PIN_SD_SCK               36        /* Feather SCK  */
#define PIN_SD_MOSI              35        /* Feather MOSI */
#define PIN_SD_MISO              37        /* Feather MISO */
#define PIN_SD_CS                12        /* Feather D12  */
#define SG_SD_MOUNT_POINT        "/sdcard"

/* ---------------- Misc board IO ---------------- */
#define PIN_STATUS_LED           13        /* red LED on the Feather */

/* ---------------- Touch vs. shot detection (tune from logged data!) -------
 * A ball contact starts when the biggest FSR rises past DETECT_FSR_THRESH.
 * Then the peak leg acceleration from the last DETECT_ACCEL_WINDOW_MS decides:
 *     peak >= SHOT  -> SHOT
 *     peak >= TOUCH -> TOUCH   (pass, dribble, light contact)
 *     otherwise     -> ignored (step, foot planted, standing)
 * Accel values are |a| in milli-g and include gravity (~1000 mg at rest). */
#define DETECT_FSR_THRESH_COUNTS 1500
#if CONFIG_SHOTGUARD_SIM
#define DETECT_TOUCH_ACCEL_MG    1300      /* sim: small slider nudges        */
#define DETECT_SHOT_ACCEL_MG     1800
#else
#define DETECT_TOUCH_ACCEL_MG    3000      /* placeholders until real data    */
#define DETECT_SHOT_ACCEL_MG     8000
#endif
#define DETECT_ACCEL_WINDOW_MS   50        /* how far back to look for the swing */
#define DETECT_REFRACTORY_MS     300       /* one contact = one event          */

/* ---------------- Logging ---------------- */
#define SG_BLOCK_SAMPLES         100       /* 100 ms of samples per SD record   */
#define SG_LOG_POOL_SIZE         8         /* record buffers between the tasks  */
#define SG_FSYNC_EVERY_RECORDS   10        /* ~1 s of data at risk on power loss */

#define SG_FW_VERSION            "0.2.0"
